/**
 * Semantic disposition authority for the 403 source-base gate rows.
 *
 * The first formation pass classified a row by the first regular-expression hit
 * over `${id} ${cmd} ${note}`. Historical prose therefore overruled the gate's
 * subject: a mention of "docs" could route a renderer gate to present-tense
 * source, while a mention of "build" could route a demo or WebGPU gate to package
 * integrity. That is exactly the kind of broad "covered generally" claim this
 * formation forbids.
 *
 * This registry deliberately never reads a legacy note to choose ownership.
 * Every source-base command identity receives one exhaustive authored decision;
 * there is no lexical classifier or fallback. Explicit reversals identify predicates
 * that reward a current defect. The generated row still binds the complete old note
 * by digest so an executor cannot silently discard a bundled clause while
 * transposing the retained property—or silently retain a rejected contrivance.
 */

const explicit = (families, focus) => ({
    families,
    focus,
    basis: "explicit-command-identity",
});

